import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { TrendingDown, TrendingUp, Calendar, MapPin, Users, User, Map, Filter, X, Download, Link as LinkIcon, ChevronLeft, ChevronRight } from 'lucide-react';

// ==================== CONSTANTS ====================
const METRICS = {
  pm25: { label: 'PM 2.5', unit: 'µg/m³', key: 'pm25' },
  co: { label: 'CO', unit: 'ppm', key: 'co' },
  temp: { label: 'Temperature', unit: '°F', key: 'temp' },
  humidity: { label: 'Humidity', unit: '%', key: 'humidity' }
};

const AQI_RANGES = {
  pm25: [
    { max: 12, label: 'Good', color: '#A7E8B1' },
    { max: 35, label: 'Moderate', color: '#FFF3B0' },
    { max: 55, label: 'Unhealthy for Sensitive', color: '#FFD6A5' },
    { max: 150, label: 'Unhealthy', color: '#FFB8B8' },
    { max: Infinity, label: 'Very Unhealthy', color: '#DDA0DD' }
  ]
};

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// ==================== HELPER FUNCTIONS ====================
const getColorForValue = (value, metric = 'pm25') => {
  const ranges = AQI_RANGES[metric] || AQI_RANGES.pm25;
  for (let range of ranges) {
    if (value <= range.max) return range.color;
  }
  return ranges[ranges.length - 1].color;
};

const getAQILabel = (value) => {
  for (let range of AQI_RANGES.pm25) {
    if (value <= range.max) return range.label;
  }
  return 'Very Unhealthy';
};

const generateCalendarData = (year, month) => {
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const daysInMonth = lastDay.getDate();
  const startingDayOfWeek = firstDay.getDay();

  const calendar = [];
  let week = new Array(7).fill(null);

  for (let i = 0; i < startingDayOfWeek; i++) {
    week[i] = null;
  }

  for (let day = 1; day <= daysInMonth; day++) {
    const dayOfWeek = (startingDayOfWeek + day - 1) % 7;

    // Generate sample data
    const pm25 = Math.floor(Math.random() * 25) + 3;
    const co = (Math.random() * 0.8 + 0.2).toFixed(2);
    const temp = Math.floor(Math.random() * 15) + 60;
    const humidity = Math.floor(Math.random() * 30) + 35;

    week[dayOfWeek] = {
      day,
      pm25,
      co: parseFloat(co),
      temp,
      humidity,
      date: new Date(year, month, day)
    };

    if (dayOfWeek === 6 || day === daysInMonth) {
      calendar.push([...week]);
      week = new Array(7).fill(null);
    }
  }

  return calendar;
};

// ==================== MAIN COMPONENT ====================
const AirQualityTracker = () => {
  // State management
  const [selectedView, setSelectedView] = useState('my');
  const [selectedMetric, setSelectedMetric] = useState('pm25');
  const [showFilters, setShowFilters] = useState(false);
  const [showLegend, setShowLegend] = useState(false);
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());
  const [filters, setFilters] = useState({
    country: 'US',
    state: 'NY',
    school: 'MTN12',
    group: 'G4',
    studentId: 'STU003'
  });

  // Data
  const calendarData = generateCalendarData(currentYear, currentMonth);
  const allDaysData = calendarData.flat().filter(d => d !== null);
  const avgValue = Math.round(
    allDaysData.reduce((sum, d) => sum + d[selectedMetric], 0) / allDaysData.length
  );

  // Helper functions
  const getFullId = () => {
    return `${filters.country}-${filters.state}-${filters.school}-${filters.group}-${filters.studentId}`;
  };

  const getViewLabel = () => {
    if (selectedView === 'my') return `${filters.studentId} (You)`;
    if (selectedView === 'team') return `${filters.group} (Your Group)`;
    return `${filters.school} (Your School)`;
  };

  const handlePrevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const handleNextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const handleDownloadData = () => {
    alert('Data download will be implemented');
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(window.location.href);
    alert('Link copied to clipboard!');
  };

  // ==================== RENDER ====================
  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-4 py-4">
        <div className="flex items-center justify-between mb-2">
          <h1 className="text-xl font-semibold text-gray-900">Air Quality</h1>
          <button 
            onClick={() => setShowFilters(true)}
            className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <Filter className="w-5 h-5 text-gray-600" />
          </button>
        </div>
        <p className="text-xs text-gray-500">{getViewLabel()}</p>
      </div>

      {/* Station Info Card */}
      <div className="px-4 py-4">
        <div 
          className="bg-white rounded-2xl p-4 shadow-sm"
          style={{ 
            background: `linear-gradient(135deg, ${getColorForValue(avgValue)}20 0%, white 100%)`
          }}
        >
          <div className="flex items-start justify-between mb-3">
            <div className="flex-1">
              <p className="text-xs text-gray-500 mb-1">STATION NAME</p>
              <h2 className="text-lg font-bold text-gray-900 mb-3">
                {filters.school} - Group {filters.group.replace('G', '')}
              </h2>

              <div className="space-y-1 text-xs">
                <div className="flex items-center gap-2">
                  <span className="text-gray-500">SENSOR:</span>
                  <span className="text-gray-900 font-medium">Government-PM2.5</span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-gray-500">LAST UPDATE:</span>
                  <span className="text-gray-900">22:00 Nov 5 2025</span>
                </div>
              </div>
            </div>

            {/* Average Display */}
            <div 
              className="rounded-xl p-4 text-center min-w-[100px]"
              style={{ backgroundColor: getColorForValue(avgValue) }}
            >
              <p className="text-xs text-gray-700 mb-1">Avg for {MONTHS[currentMonth].slice(0, 3)}</p>
              <p className="text-4xl font-bold text-gray-900">{avgValue}</p>
              <p className="text-xs text-gray-700 mt-1">{METRICS[selectedMetric].unit}</p>
            </div>
          </div>

          {/* Actions */}
          <div className="flex gap-2">
            <button 
              onClick={handleCopyLink}
              className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-white border border-gray-200 rounded-lg text-xs font-medium text-gray-700 hover:bg-gray-50"
            >
              <LinkIcon className="w-4 h-4" />
              COPY LINK
            </button>
            <button 
              onClick={handleDownloadData}
              className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-blue-600 rounded-lg text-xs font-medium text-white hover:bg-blue-700"
            >
              <Download className="w-4 h-4" />
              DOWNLOAD DATA
            </button>
          </div>
        </div>
      </div>

      {/* View Toggle */}
      <div className="px-4 mb-4">
        <div className="bg-gray-200 rounded-xl p-1 flex">
          <button
            onClick={() => setSelectedView('my')}
            className={`flex-1 py-2 px-3 rounded-lg text-xs font-medium transition-all ${
              selectedView === 'my' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-600'
            }`}
          >
            My Data
          </button>
          <button
            onClick={() => setSelectedView('team')}
            className={`flex-1 py-2 px-3 rounded-lg text-xs font-medium transition-all ${
              selectedView === 'team' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-600'
            }`}
          >
            Team
          </button>
          <button
            onClick={() => setSelectedView('class')}
            className={`flex-1 py-2 px-3 rounded-lg text-xs font-medium transition-all ${
              selectedView === 'class' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-600'
            }`}
          >
            School
          </button>
        </div>
      </div>

      {/* Metric Selector */}
      <div className="px-4 mb-4">
        <div className="bg-white rounded-xl p-3 shadow-sm">
          <div className="flex items-center justify-between mb-2">
            <p className="text-xs font-semibold text-gray-700">SELECT METRIC</p>
            <button 
              onClick={() => setShowLegend(!showLegend)}
              className="text-xs text-blue-600 font-medium"
            >
              {showLegend ? 'Hide' : 'Show'} Legend
            </button>
          </div>
          <div className="grid grid-cols-4 gap-2">
            {Object.entries(METRICS).map(([key, metric]) => (
              <button
                key={key}
                onClick={() => setSelectedMetric(key)}
                className={`py-2 px-2 rounded-lg text-xs font-medium transition-colors ${
                  selectedMetric === key
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 text-gray-700'
                }`}
              >
                {metric.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Legend */}
      {showLegend && selectedMetric === 'pm25' && (
        <div className="px-4 mb-4">
          <div className="bg-white rounded-xl p-3 shadow-sm">
            <p className="text-xs font-semibold text-gray-700 mb-2">MEASUREMENTS LEGEND ({METRICS[selectedMetric].unit})</p>
            <div className="flex items-center gap-1">
              {AQI_RANGES.pm25.slice(0, -1).map((range, idx) => {
                const prevMax = idx === 0 ? 0 : AQI_RANGES.pm25[idx - 1].max;
                return (
                  <div key={idx} className="flex-1">
                    <div 
                      className="h-6 flex items-center justify-center text-xs font-medium text-gray-700"
                      style={{ backgroundColor: range.color }}
                    >
                      {prevMax}-{range.max}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Calendar */}
      <div className="px-4 mb-6">
        <div className="bg-white rounded-xl p-4 shadow-sm">
          {/* Calendar Header */}
          <div className="flex items-center justify-between mb-4">
            <button 
              onClick={handlePrevMonth}
              className="p-2 hover:bg-gray-100 rounded-lg"
            >
              <ChevronLeft className="w-5 h-5 text-gray-600" />
            </button>
            <h3 className="text-base font-bold text-gray-900">
              {MONTHS[currentMonth]} {currentYear}
            </h3>
            <button 
              onClick={handleNextMonth}
              className="p-2 hover:bg-gray-100 rounded-lg"
            >
              <ChevronRight className="w-5 h-5 text-gray-600" />
            </button>
          </div>

          {/* Day Headers */}
          <div className="grid grid-cols-7 gap-1 mb-2">
            {DAYS.map(day => (
              <div key={day} className="text-center text-xs font-medium text-gray-500 py-1">
                {day}
              </div>
            ))}
          </div>

          {/* Calendar Grid */}
          <div className="space-y-1">
            {calendarData.map((week, weekIdx) => (
              <div key={weekIdx} className="grid grid-cols-7 gap-1">
                {week.map((dayData, dayIdx) => (
                  <div
                    key={dayIdx}
                    className="aspect-square"
                  >
                    {dayData && (
                      <div
                        className="w-full h-full rounded-lg flex flex-col items-center justify-center"
                        style={{ backgroundColor: getColorForValue(dayData[selectedMetric], selectedMetric) }}
                      >
                        <span className="text-xs text-gray-600">{dayData.day}</span>
                        <span className="text-sm font-bold text-gray-900">
                          {Math.round(dayData[selectedMetric])}
                        </span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Educational Fact */}
      <div className="px-4 mb-6">
        <div className="bg-blue-50 rounded-xl p-4 border border-blue-100">
          <div className="flex gap-3">
            <span className="text-xl">💡</span>
            <div>
              <h3 className="text-sm font-semibold text-blue-900 mb-1">Did you know?</h3>
              <p className="text-xs text-blue-800">
                PM 2.5 particles are 30 times smaller than a human hair. They can travel deep into your lungs and even enter your bloodstream.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Filters Modal */}
      {showFilters && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 flex items-end justify-center z-50"
          onClick={() => setShowFilters(false)}
        >
          <div 
            className="bg-white rounded-t-3xl w-full max-w-lg p-6 max-h-[80vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-xl font-bold text-gray-900">Filters</h2>
              <button 
                onClick={() => setShowFilters(false)}
                className="p-2 hover:bg-gray-100 rounded-lg"
              >
                <X className="w-5 h-5 text-gray-600" />
              </button>
            </div>

            {/* Current ID */}
            <div className="bg-blue-50 rounded-xl p-4 mb-6 border border-blue-100">
              <p className="text-xs text-blue-600 font-medium mb-1">Your ID</p>
              <p className="text-sm font-mono text-blue-900">{getFullId()}</p>
            </div>

            {/* Filter Controls */}
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Country</label>
                <select 
                  value={filters.country}
                  onChange={(e) => setFilters({...filters, country: e.target.value})}
                  className="w-full p-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-400"
                >
                  <option value="US">United States</option>
                  <option value="CA">Canada</option>
                  <option value="UK">United Kingdom</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">State/Province</label>
                <select 
                  value={filters.state}
                  onChange={(e) => setFilters({...filters, state: e.target.value})}
                  className="w-full p-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-400"
                >
                  <option value="NY">New York</option>
                  <option value="CA">California</option>
                  <option value="TX">Texas</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">School/Site Code</label>
                <input
                  type="text"
                  value={filters.school}
                  onChange={(e) => setFilters({...filters, school: e.target.value.toUpperCase()})}
                  placeholder="e.g., MTN12"
                  className="w-full p-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-400"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Class/Group</label>
                <div className="grid grid-cols-4 gap-2">
                  {['G1', 'G2', 'G3', 'G4', 'G5', 'G6'].map(group => (
                    <button
                      key={group}
                      onClick={() => setFilters({...filters, group})}
                      className={`p-3 rounded-xl text-sm font-medium transition-colors ${
                        filters.group === group ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-700'
                      }`}
                    >
                      {group}
                    </button>
                  ))}
                </div>
              </div>

              {selectedView === 'my' && (
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Your Student ID</label>
                  <input
                    type="text"
                    value={filters.studentId}
                    onChange={(e) => setFilters({...filters, studentId: e.target.value.toUpperCase()})}
                    placeholder="e.g., STU003"
                    className="w-full p-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-400"
                  />
                </div>
              )}
            </div>

            <button
              onClick={() => setShowFilters(false)}
              className="w-full mt-6 py-3 bg-blue-600 text-white font-medium rounded-xl hover:bg-blue-700"
            >
              Apply Filters
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AirQualityTracker;
